SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);Alarm(400);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C54/expanded_forward.m";load "work/deg10/continuation_20261031b/C54/inputs/pair_af_place_linear.m";
root:="work/deg10/continuation_20261031b/C54/";a:=eval Read(root cat "inputs/target27_proven_picard.m");k:=GF(5);PK:=PolynomialRing(k);B<t>:=FunctionField(k);R<Y>:=PolynomialRing(B);
function Rat(v)return B!(PK!v[1])/B!(PK!v[2]);end function;F<y>:=FunctionField(R![Rat(v):v in a[1]]);assert Genus(F)eq 13;
function FF(v)return F![Rat(z):z in v];end function;OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function Prime(v)O:=v[2]eq 1 select OF else OI;I:=ideal<O|[FF(z):z in v[3]]>;p:=Place(I);assert Degree(p)eq v[1];return p;end function;
fb:=[Prime([*a[3][i],a[2][i],a[4][i]*]):i in[1..#a[3]]];A:=Divisor(Prime(a[12]));Z:=FreeAbelianGroup(#a[6][1]);G,q:=quo<Z|[Z!v:v in a[6]]>;H:=sub<G|[q(Z!v):v in a[13]]>;fc:=[q(Z!v):v in a[5]];basehit:=[i:i in[1..#fb]|Divisor(fb[i])eq A];assert #basehit eq 1;ac:=fc[basehit[1]];
for d in[5,6]do ex:=eval Read(root cat Sprintf("expanded_d%o.m",d));for row in ex do Append(~fb,Prime(row[1]));Append(~fc,q(Z!row[2])+d*ac);end for;end for;print "D31B_C54_EXPANDED_FRAME_READY",#fb,Cputime(tt);coords:=[FF(v):v in a[7]];ph,wh:=C54ExpandedDirectRR(F,fb,fc,G,A,root cat "member_all_class.log");src:=eval Read(root cat "member_two_isogenies_all.m");dy:=eval Read(root cat "dyadic_rigidity_v2.m");rows:=[* *];tm:=Cputime();for row in src[1]do id,ky:=Explode(row);d:=ky[1];K:=ext<k|PK!ky[4..4+d]>;gg:=K.1;b:=Evaluate(PK!ky[5+d..4+2*d],gg);c:=Evaluate(PK!ky[5+2*d..4+3*d],gg);E:=EllipticCurve([K|1-c,-b,-b,0,0]);P:=E![0,0];assert Order(P)eq 27;pt:=C48PairAFPlaceLinear(coords,TateNormalForm_xy(E,P));assert Degree(pt)eq d;cl:=ph(Divisor(pt)-d*A);Append(~rows,[*id,d,Eltseq(cl)*]);end for;fprintf wh,"]\n";Flush(wh);
G2:=AbelianGroup(dy[1]);Z2:=FreeAbelianGroup(#dy[3]);h2:=hom<Z2->G2|[G2!v:v in dy[6]]>;ib:=Index(dy[4],1);isg:=Index(a[14],dy[3][ib]);ca2:=q(Z!a[10][isg]);cg5:=[q(Z!a[10][Index(a[14],dy[3][j])])-dy[4][j]*ca2:j in[1..#dy[3]]];h5:=hom<Z2->G|cg5>;assert #Image(h5)eq #Image(h2)and #Image(h2)eq 472473;
allowed:=AssociativeArray();for r in dy[8]do c1:=G2!r[7];c2:=G2!r[8];if not IsDefined(allowed,c1)then allowed[c1]:={G!h5((c2)@@h2)};else Include(~allowed[c1],h5((c2)@@h2));end if;end for;
cs:=AssociativeArray();cs[0]:={G!0};for n in[1..8]do cs[n]:={G|};for j in[1..#a[9]]do e:=a[9][j];if e le n then for v in cs[n-e]do Include(~cs[n],v+q(Z!a[10][j])-e*ca2);end for;end if;end for;end for;
clp:=AssociativeArray();for r in rows do clp[r[1]]:=q(Z!r[3])-r[2]*ca2;end for;tests:=[* *];left:=[];for r in src[3]do id,mi,ci,cl,cd,terms:=Explode(r);nc:=&+[G|z[2]*clp[z[1]]:z in terms];yes:=#(allowed[G2!cl]meet{nc+c:c in cs[cd]})gt 0;Append(~tests,[*id,mi,ci,cd,yes*]);if yes then Append(~left,id);end if;end for;
Write(root cat "member_all_classes.m",Sprint([*rows,tests,left*]):Overwrite:=true);print "D31B_C54_MEMBER_ALL_CLASS_COMPLETE",#rows,#tests,#left,Cputime(tm),Cputime(tt);quit;
